int n, m; 
char a [maxn][maxn] ; 
int dp [maxn][maxn] ; 

int sx , sy , ex , ey ; 
int dx [] = {0,1,-1,0} ; 
int dy [] = {1,0,0,-1} ; 

string DIR = "RDUL" ; 

bool inside ( int x , int y ) 
{
    return ( x >= 1 && x <= n && y >= 1 && y <= m ) ; 
}

int trace [maxn][maxn] ; 
signed main () 
{
    ios_base::sync_with_stdio(0); 
    cin.tie(0);cout.tie(0); 
    cin >> n >> m ; 
    for ( int i = 1 ; i <= n ; i ++ ) for ( int j = 1 ; j <= m ; j ++ ) 
    {
        cin >> a [i][j] ; 
        if ( a [i][j] == 'A' ) sx = i , sy = j ; 
        else if ( a[i][j] == 'B' ) ex = i , ey = j ; 
    }

    queue <pii> q ; 
    q . push ({sx,sy}) ;
    memset (dp,-1,sizeof dp) ;  
    dp [sx][sy] = 0 ; 
    while ( !q.empty()) 
    {
        auto [u,v] = q.front() ; q.pop() ; 
        for ( int i = 0 ; i < 4 ; i ++ ) 
        {
            int x = u + dx [i] , y = v + dy [i] ; 
            if ( inside (x,y) && a [x][y] != '#' && dp [x][y] == -1 ) 
            {
                dp [x][y] = dp [u][v] + 1 ; 
                trace [x][y] = i ; 
                q . push ({x,y}) ; 
            }
        }
    }

    if ( dp [ex][ey] == -1 ) 
    {
        cout << "NO\n" ; 
    }
    else 
    {
        cout << "YES\n" ; 
        cout << dp [ex][ey] << "\n" ; 
        vector <char> road ; 
        while ( true ) 
        {
            road.pb(DIR[trace[ex][ey]]) ; 
            int nx = ex - dx [trace[ex][ey]] ; 
            int ny = ey - dy [trace[ex][ey]] ; 
            ex = nx , ey = ny ;
            if ( ex == sx && ey == sy ) break ; 
        }
        reverse(road.begin(),road.end()) ; 
        for ( auto x : road ) cout << x ; 
    }
    return 0;
}
